STUDIES = json.loads((ROOT / 'prompts.json').read_text())['studies']
for study in STUDIES:
    if study['id'] == '04-shadow':
        study['description'] = 'Crisp sage offset behind a normally shaped box.'
    if study['id'] in ('02-square', '04-shadow', '08-charcoal'):
        study['description'] += ' Paper proof.'
