def esc(s): return html.escape(str(s), quote=True)
def sizes(id, values=(16, 24, 32, 48, 64)):
    return ''.join(f'<span><img class="size-sample" data-size="{n}" src="marks/{id}.png" alt="" width="{n}" height="{n}"><small>{n}</small></span>' for n in values)

cards = ''.join(f'''<article class="concept" id="{s['id']}">
  <button class="art-stage zoom" data-image="marks/{s['id']}.png" data-title="{esc(s['name'])}" aria-label="Enlarge {esc(s['name'])}"><img src="marks/{s['id']}.png" alt="{esc(s['name'])} smiling box mark"></button>
  <div class="concept-text"><span class="number">{s['id'][:2]}</span><h3>{esc(s['name'])}</h3><p>{esc(s['description'])}</p></div>
  <div class="size-strip preview-surface">{sizes(s['id'])}</div>
  <button class="compare-this" data-id="{s['id']}">Compare this option ↗</button>
</article>''' for s in STUDIES)
refs = ''.join(f'''<article class="reference"><div class="reference-image {cls}"><img src="downloads/marks/{file}" alt="{esc(name)} official reference" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span hidden>Download reference locally</span></div><h3>{esc(name)}</h3><p>{esc(note)}</p><a href="{url}" target="_blank" rel="noreferrer">Source ↗</a></article>''' for name,file,url,note,cls in REFERENCES)
guides = ''.join(f'''<article class="guide"><h3>{esc(name)}</h3><p>{esc(note)}</p><div><a href="downloads/guides/{file}" target="_blank" rel="noreferrer">Local {file.rsplit('.',1)[1].upper()} ↗</a><a href="{url}" target="_blank" rel="noreferrer">Original ↗</a></div></article>''' for name,file,url,note in GUIDES)
options = ''.join(f'<option value="{s["id"]}">{s["id"][:2]} · {esc(s["name"])}</option>' for s in STUDIES)
data = json.dumps([{k:s[k] for k in ('id','name','description')} for s in STUDIES]).replace('<', '\\u003c')
